package com.ilp.login;

import java.util.*;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

// WebController.java: builds the page from your steps. Students do NOT edit this file.
// Demo user already saved:  rajeev / ilp123
@RestController
public class WebController {
    static final Map<String, String> users = new LinkedHashMap<>(Map.of("rajeev", "ilp123")); // username -> password
    static String msg = "", user = null;
    static boolean ok = false, added = false;
    static final String HTML = "text/html;charset=UTF-8";

    @GetMapping(value = "/", produces = HTML)
    public String home() {
        if (Checks.done(5) && !added) { Step05MyUser.addMyUser(users); added = true; }
        String m = msg.isEmpty() ? "" : "<div class=\"msg " + (ok ? "ok" : "bad") + "\">" + msg + "</div>";
        String body;
        if (user != null) {
            String u = Ui.esc(user);
            body = "<div class=\"card\">" + Ui.part(8, () -> Step08Welcome.welcome(u))
                + "<p>You are logged in.</p><a href=\"/logout\"><button class=\"alt\">Logout</button></a></div>";
        } else {
            String login = "<form method=\"post\" action=\"/login\">" + Ui.part(2, Step02UsernameBox::usernameBox)
                + Ui.part(3, Step03PasswordBox::passwordBox) + Ui.part(4, Step04LoginButton::loginButton) + "</form>";
            String reg = Checks.done(9)
                ? "<form method=\"post\" action=\"/register\"><input name=\"username\" placeholder=\"New username\"><input name=\"password\" type=\"password\" placeholder=\"New password\"><button class=\"amber\">Sign up</button></form>"
                : Ui.box(9);
            String rule = Checks.done(10) ? "<p style=\"color:#6b7480\">Password must have 6 or more characters.</p>" : Ui.box(10);
            body = "<div class=\"card\">" + Ui.part(1, Step01Header::header) + m + login + "</div>"
                + "<div class=\"card\"><h2>New here? Sign up</h2>" + reg + rule + "</div>";
        }
        StringBuilder names = new StringBuilder();
        for (String k : users.keySet()) names.append(names.length() > 0 ? ", " : "").append(Ui.esc(k));
        String saved = "<div class=\"card\"><h2>Saved users</h2><p>" + names + "</p>" + (Checks.done(5) ? "" : Ui.box(5)) + "</div>";
        return Ui.page(body + saved);
    }

    @PostMapping("/login")
    public ResponseEntity<Void> login(@RequestParam(defaultValue = "") String username, @RequestParam(defaultValue = "") String password) {
        String u = username.trim();
        ok = false;
        if (!Checks.done(6)) msg = "Step 6 is not done yet, so we cannot check the username.";
        else if (!Step06UserExists.userExists(users, u)) msg = "User not found ❌  (try rajeev / ilp123)";
        else if (!Checks.done(7)) msg = "User found ✅, but step 7 is not done yet, so we cannot check the password.";
        else if (!Step07PasswordOk.passwordOk(users, u, password)) msg = "Wrong password ❌";
        else { user = u; msg = ""; }
        return home302();
    }

    @PostMapping("/register")
    public ResponseEntity<Void> register(@RequestParam(defaultValue = "") String username, @RequestParam(defaultValue = "") String password) {
        String u = username.trim();
        ok = false;
        if (u.isEmpty()) msg = "Type a username to register.";
        else if (Checks.done(10) && !Step10StrongPassword.strongPassword(password)) msg = "Password too short ❌  It needs 6 or more characters.";
        else if (Checks.done(9)) { Step09Register.register(users, u, password); ok = true; msg = "Account created for " + Ui.esc(u) + " ✅  Now log in."; }
        return home302();
    }

    @GetMapping("/logout")
    public ResponseEntity<Void> logout() {
        user = null; msg = "";
        return home302();
    }

    // ==============================================================
    //  API: ready-made. Call it with curl: commands/08_api_crud.txt
    //  (Java keeps data in memory. SQL for each call is in the comments.)
    // ==============================================================
    @GetMapping("/api/users")                            // SELECT username FROM users
    public List<String> apiUsers() {
        return new ArrayList<>(new TreeSet<>(users.keySet()));
    }

    @PostMapping("/api/signup")                          // INSERT INTO users ...
    public ResponseEntity<Object> apiSignup(@RequestBody Map<String, Object> body) {
        String u = String.valueOf(body.getOrDefault("username", "")).trim();
        String p = String.valueOf(body.getOrDefault("password", ""));
        if (u.isEmpty() || p.isEmpty()) return ResponseEntity.status(400).body(Map.of("error", "username and password are required"));
        if (users.containsKey(u)) return ResponseEntity.status(409).body(Map.of("error", "username already taken"));
        if (p.length() < 6) return ResponseEntity.status(400).body(Map.of("error", "password needs 6 or more characters"));
        users.put(u, p);
        return ResponseEntity.status(201).body(Map.of("message", "account created", "username", u));
    }

    @PostMapping("/api/login")                           // SELECT password FROM users WHERE username = ...
    public ResponseEntity<Object> apiLogin(@RequestBody Map<String, Object> body) {
        String u = String.valueOf(body.getOrDefault("username", "")).trim();
        String p = String.valueOf(body.getOrDefault("password", ""));
        if (!p.equals(users.get(u))) return ResponseEntity.status(401).body(Map.of("error", "wrong username or password"));
        return ResponseEntity.ok(Map.of("message", "Welcome, " + u + "!"));
    }

    static ResponseEntity<Void> home302() {
        return ResponseEntity.status(302).header("Location", "/").build();
    }
}
